#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

# symbol_id => { import_path, pkg, recv, name, file, line, exported }
my %symbols;
# import_path => package dir
my %path_to_dir;
# dir => import_path (primary)
my %dir_to_path;

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or return '';
    local $/; my $c = <$fh>; close $fh;
    return $c;
}

sub pkg_dir_from_path {
    my ($path) = @_;
    return undef unless $path =~ m{^$ROOT/internal/};
    my $dir = $path; $dir =~ s{/[^/]+$}{};
    return $dir;
}

sub import_path_from_dir {
    my ($dir) = @_;
  return undef unless $dir =~ m{^$ROOT/internal/(.+)$} || $dir eq "$ROOT/internal";
    my $suffix = $1 // '';
    return $suffix eq '' ? "$MODULE/internal" : "$MODULE/internal/$suffix";
}

sub parse_pkg {
    my ($content) = @_;
    return '' unless $content =~ /^package\s+(\w+)/m;
    return $1;
}

sub parse_imports {
    my ($content) = @_;
    my %imports;
    while ($content =~ /^\s*(\w+)\s+"([^"]+)"/mg) {
        $imports{$2} = $1;  # path => alias (named import)
    }
    while ($content =~ /^\s*"([^"]+)"/mg) {
        my $path = $1;
        next if exists $imports{$path};
        my $alias = $path;
        $alias =~ s{.*/}{};
        $imports{$path} = $alias;
    }
    return %imports;
}

sub recv_type {
    my ($recv) = @_;
    return '' unless defined $recv && $recv ne '';
    $recv =~ s/^\*//;
    $recv =~ s/^[\w.]+\.//;  # strip package qualifier on type
    return $recv;
}

sub is_exported {
    my ($name) = @_;
    return $name =~ /^[A-Z]/;
}

# Pass 1: collect declarations in internal/
find({
    wanted => sub {
        return unless /\.go$/;
        return if /_test\.go$/;
        my $path = $File::Find::name;
        return unless $path =~ m{^$ROOT/internal/};
        my $content = read_file($path);
        my $pkg = parse_pkg($content);
        my $dir = pkg_dir_from_path($path);
        my $import_path = import_path_from_dir($dir);
        $dir_to_path{$dir} = $import_path;
        $path_to_dir{$import_path} = $dir;

        my @lines = split /\n/, $content;
        for my $i (0..$#lines) {
            my $line = $lines[$i];
            next unless $line =~ /^func\s+/;
            # skip func keyword only lines by joining until opening brace or paren balance
            my $decl = $line;
            my $j = $i;
            while ($decl !~ /\)\s*(?:\([^)]*\)\s*)?[\w*]+\s*\(/ && $j < $#lines) {
                $j++; $decl .= " " . $lines[$j];
            }
            my ($recv, $name);
            if ($decl =~ /^func\s+\(([^)]*)\)\s+([A-Za-z_]\w*)\s*\(/) {
                ($recv, $name) = ($1, $2);
            } elsif ($decl =~ /^func\s+([A-Za-z_]\w*)\s*\(/) {
                $name = $1; $recv = '';
            } else {
                next;
            }
            $recv = recv_type($recv);
            my $id = join '|', $import_path, $recv, $name;
            $symbols{$id} = {
                import_path => $import_path,
                pkg => $pkg,
                recv => $recv,
                name => $name,
                file => $path,
                line => $i + 1,
                exported => is_exported($name) ? 1 : 0,
                dir => $dir,
            };
        }
    },
    no_chdir => 1,
}, "$ROOT/internal");

# Pass 2: count call sites repo-wide
my %call_sites;  # symbol_id => { "file:line" => 1 }

sub add_call {
    my ($id, $file, $line) = @_;
    $call_sites{$id}{"$file:$line"} = 1;
}

find({
    wanted => sub {
        return unless /\.go$/;
        my $path = $File::Find::name;
        return unless $path =~ m{^$ROOT/};
        my $content = read_file($path);
        my $pkg = parse_pkg($content);
        my %imports = parse_imports($content);
        my $file_dir = $path; $file_dir =~ s{/[^/]+$}{};

        # map alias -> import_path for this file
        my %alias_to_path;
        for my $ip (keys %imports) {
            $alias_to_path{$imports{$ip}} = $ip;
        }

        my @lines = split /\n/, $content;
        for my $i (0..$#lines) {
            my $ln = $i + 1;
            my $line = $lines[$i];
            next if $line =~ /^\s*\/\//;
            next if $line =~ /^\s*func\s+/;  # skip declarations on same line heuristic

            # Qualified calls: alias.FuncName(
            while ($line =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
                my ($alias, $fname) = ($1, $2);
                next if $alias eq 'http' || $alias eq 'json' || $alias eq 'fmt' || $alias eq 'strings';
                my $ip = $alias_to_path{$alias};
                next unless defined $ip && $ip =~ m{^$MODULE/internal};
                my $id = join '|', $ip, '', $fname;
                if (exists $symbols{$id}) {
                    add_call($id, $path, $ln);
                }
                # also try methods on constructors? skip
            }

            # Method calls: .MethodName(
            while ($line =~ /\.([A-Za-z_]\w*)\s*\(/g) {
                my $mname = $1;
                # match any symbol in internal with this method name
                for my $id (keys %symbols) {
                    my $s = $symbols{$id};
                    next unless $s->{recv} ne '' && $s->{name} eq $mname;
                    # same-package method calls are common; count if file could call it
                    # For cross-package: count all .Method( as potential (over-approx for common names)
                    # Refine: if method is unexported, only same import_path dir tree package
                    if (!$s->{exported}) {
                        next unless $file_dir eq $s->{dir};
                    }
                    add_call($id, $path, $ln);
                }
            }

            # Unqualified function calls in same package
            if (exists $dir_to_path{$file_dir}) {
                my $ip = $dir_to_path{$file_dir};
                while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
                    my $fname = $1;
                    next if $fname eq 'if' || $fname eq 'for' || $fname eq 'switch' || $fname eq 'return' || $fname eq 'func' || $fname eq 'make' || $fname eq 'new' || $fname eq 'len' || $fname eq 'cap' || $fname eq 'append' || $fname eq 'delete' || $fname eq 'panic' || $fname eq 'go' || $fname eq 'defer' || $fname eq 'close' || $fname eq 'copy' || $fname eq 'complex' || $fname eq 'real' || $fname eq 'imag';
                    my $id = join '|', $ip, '', $fname;
                    if (exists $symbols{$id}) {
                        add_call($id, $path, $ln);
                    }
                }
            }
        }
    },
    no_chdir => 1,
}, $ROOT);

# Remove self-declaration lines from call sites
for my $id (keys %symbols) {
    my $s = $symbols{$id};
    my $decl = "$s->{file}:$s->{line}";
    delete $call_sites{$id}{$decl};
    # also remove nearby declaration lines (multi-line func)
    for my $site (keys %{$call_sites{$id}}) {
        if ($site =~ /^(\Q$s->{file}\E):(\d+)$/) {
            my $l = $2;
            if ($l >= $s->{line} && $l <= $s->{line} + 5) {
                my $content = read_file($s->{file});
                my @lines = split /\n/, $content;
                if ($l <= $#lines + 1 && $lines[$l-1] =~ /^\s*func\s+/) {
                    delete $call_sites{$id}{$site};
                }
            }
        }
    }
}

# Rank
my @ranked = sort {
    my $ca = scalar(keys %{$call_sites{$a} // {}});
    my $cb = scalar(keys %{$call_sites{$b} // {}});
    $cb <=> $ca || $a cmp $b;
} keys %symbols;

print "TOP 30 BY DISTINCT CALL SITES\n";
print "=" x 80, "\n";
my $n = 0;
for my $id (@ranked) {
    my $count = scalar(keys %{$call_sites{$id} // {}});
    next if $count == 0;
    last if ++$n > 30;
    my $s = $symbols{$id};
    my $sym = $s->{recv} ? "($s->{recv}).$s->{name}" : "$s->{name}";
    print sprintf("%3d  %s\n     %s:%d  pkg=%s  path=%s\n", $count, $sym, $s->{file}, $s->{line}, $s->{pkg}, $s->{import_path});
}

# Detailed top 5
print "\nDETAILED TOP 5\n";
print "=" x 80, "\n";
$n = 0;
for my $id (@ranked) {
    my $count = scalar(keys %{$call_sites{$id} // {}});
    next if $count == 0;
    last if ++$n > 5;
    my $s = $symbols{$id};
  my $sym = $s->{recv} ? "($s->{recv}).$s->{name}" : "$s->{name}";
    print "\n$sym => $count call sites\n";
    my $sites = $call_sites{$id};
    my $shown = 0;
    for my $site (sort keys %$sites) {
        print "  $site\n";
        last if ++$shown >= 15;
    }
    print "  ...\n" if $count > 15;
}

