            add_call($id, $path, $ln) if exists $symbols{$id};
        }

        while ($line =~ /\.([A-Za-z_]\w*)\s*\(/g) {
            my $mname = $1;
            next unless exists $methods_by_name{$mname};
            for my $id (@{$methods_by_name{$mname}}) {
                my $s = $symbols{$id};
                if (!$s->{exported}) {
                    next unless $file_dir eq $s->{dir};
                }
                add_call($id, $path, $ln);
            }
        }

        if (exists $dir_to_path{$file_dir}) {
            my $ip = $dir_to_path{$file_dir};
            while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
                my $fname = $1;
                next if $builtin{$fname};
                my $id = join '|', $ip, '', $fname;
                add_call($id, $path, $ln) if exists $symbols{$id};
            }
        }
    }
}

# Strip declaration lines
for my $id (keys %symbols) {
    my $s = $symbols{$id};
    delete $call_sites{$id}{"$s->{file}:$s->{line}"};
    for my $site (keys %{$call_sites{$id} // {}}) {
        if ($site =~ /^(\Q$s->{file}\E):(\d+)$/) {
