#!/usr/bin/perl
use strict;
use warnings;

my $ROOT = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

my %symbols;
my %dir_to_path;
my %call_sites;

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or return '';
    local $/; my $c = <$fh>; close $fh;
    return $c;
}

sub pkg_dir_from_path {
    my ($path) = @_;
    return undef unless $path =~ m{^$ROOT/internal/};
    my $dir = $path; $dir =~ s{/[^/]+$}{};
    return $dir;
}

sub import_path_from_dir {
    my ($dir) = @_;
    return undef unless $dir =~ m{^$ROOT/internal/(.+)$} || $dir eq "$ROOT/internal";
    my $suffix = $1 // '';
    return $suffix eq '' ? "$MODULE/internal" : "$MODULE/internal/$suffix";
}

sub parse_pkg {
    my ($content) = @_;
    return '' unless $content =~ /^package\s+(\w+)/m;
    return $1;
}

sub parse_imports {
    my ($content) = @_;
    my %imports;
    while ($content =~ /^\s*(\w+)\s+"([^"]+)"/mg) {
        $imports{$2} = $1;
    }
    while ($content =~ /^\s*"([^"]+)"/mg) {
        my $path = $1;
        next if exists $imports{$path};
        my $alias = $path; $alias =~ s{.*/}{};
        $imports{$path} = $alias;
    }
    return %imports;
}

sub recv_type {
    my ($recv) = @_;
    return '' unless defined $recv && $recv ne '';
    $recv =~ s/^\*//;
    $recv =~ s/^[\w.]+\.//;
    return $recv;
}

sub is_exported { $_[0] =~ /^[A-Z]/ }

sub list_go_files {
    my ($base, $test) = @_;
    open my $fh, '-|', 'find', $base, '-name', '*.go' or die $!;
    my @files;
    while (<$fh>) {
        chomp;
        next if !$test && /_test\.go$/;
        push @files, $_;
    }
    close $fh;
    return @files;
}

sub add_call {
    my ($id, $file, $line) = @_;
    $call_sites{$id}{"$file:$line"} = 1;
}

my %builtin = map { $_ => 1 } qw(if for switch return func make new len cap append delete panic go defer close copy complex real imag);

# Pass 1
for my $path (list_go_files("$ROOT/internal", 0)) {
    my $content = read_file($path);
    my $pkg = parse_pkg($content);
    my $dir = pkg_dir_from_path($path);
    my $import_path = import_path_from_dir($dir);
    $dir_to_path{$dir} = $import_path;

    my @lines = split /\n/, $content;
    for my $i (0..$#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+/;
        my $decl = $line;
        my $j = $i;
        while ($decl !~ /\)\s*(?:\([^)]*\)\s*)?[\w*]+\s*\(/ && $j < $#lines) {
            $j++; $decl .= " " . $lines[$j];
        }
        my ($recv, $name);
        if ($decl =~ /^func\s+\(([^)]*)\)\s+([A-Za-z_]\w*)\s*\(/) {
            ($recv, $name) = ($1, $2);
        } elsif ($decl =~ /^func\s+([A-Za-z_]\w*)\s*\(/) {
            $name = $1; $recv = '';
        } else { next; }
        $recv = recv_type($recv);
        my $id = join '|', $import_path, $recv, $name;
        $symbols{$id} = {
            import_path => $import_path, pkg => $pkg, recv => $recv, name => $name,
            file => $path, line => $i + 1, exported => is_exported($name), dir => $dir,
        };
    }
}

# Build method name index
my %methods_by_name;
for my $id (keys %symbols) {
    my $s = $symbols{$id};
    next unless $s->{recv} ne '';
    push @{$methods_by_name{$s->{name}}}, $id;
}

# Pass 2
for my $path (list_go_files($ROOT, 1)) {
    my $content = read_file($path);
    my %imports = parse_imports($content);
    my %alias_to_path;
    for my $ip (keys %imports) { $alias_to_path{$imports{$ip}} = $ip; }

    my $file_dir = $path; $file_dir =~ s{/[^/]+$}{};
    my @lines = split /\n/, $content;

    for my $i (0..$#lines) {
        my $ln = $i + 1;
        my $line = $lines[$i];
        next if $line =~ /^\s*\/\//;

        while ($line =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($alias, $fname) = ($1, $2);
            my $ip = $alias_to_path{$alias};
            next unless defined $ip && $ip =~ m{^$MODULE/internal};
            my $id = join '|', $ip, '', $fname;
            add_call($id, $path, $ln) if exists $symbols{$id};
        }

        while ($line =~ /\.([A-Za-z_]\w*)\s*\(/g) {
            my $mname = $1;
            next unless exists $methods_by_name{$mname};
            for my $id (@{$methods_by_name{$mname}}) {
                my $s = $symbols{$id};
                if (!$s->{exported}) {
                    next unless $file_dir eq $s->{dir};
                }
                add_call($id, $path, $ln);
            }
        }

        if (exists $dir_to_path{$file_dir}) {
            my $ip = $dir_to_path{$file_dir};
            while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
                my $fname = $1;
                next if $builtin{$fname};
                my $id = join '|', $ip, '', $fname;
                add_call($id, $path, $ln) if exists $symbols{$id};
            }
        }
    }
}

# Strip declaration lines
for my $id (keys %symbols) {
    my $s = $symbols{$id};
    delete $call_sites{$id}{"$s->{file}:$s->{line}"};
    for my $site (keys %{$call_sites{$id} // {}}) {
        if ($site =~ /^(\Q$s->{file}\E):(\d+)$/) {
