            }
        }
    }
}

my @ranked = sort {
    (scalar(keys %{$call_sites{$b} // {}}) <=> scalar(keys %{$call_sites{$a} // {}})) || $a cmp $b
} keys %symbols;

print "TOP 35 BY DISTINCT CALL SITES\n", "=" x 80, "\n";
my $n = 0;
for my $id (@ranked) {
    my $count = scalar(keys %{$call_sites{$id} // {}});
    next if $count == 0;
    last if ++$n > 35;
    my $s = $symbols{$id};
    my $sym = $s->{recv} ? "($s->{recv}).$s->{name}" : "$s->{name}";
    print sprintf("%3d  %s\n     %s:%d  pkg=%s  import=%s\n", $count, $sym, $s->{file}, $s->{line}, $s->{pkg}, $s->{import_path});
}

print "\nDETAILED TOP 8\n", "=" x 80, "\n";
$n = 0;
for my $id (@ranked) {
    my $count = scalar(keys %{$call_sites{$id} // {}});
    next if $count == 0;
    last if ++$n > 8;
    my $s = $symbols{$id};
    my $sym = $s->{recv} ? "($s->{recv}).$s->{name}" : "$s->{name}";
    print "\n$sym => $count sites\n";
    my $shown = 0;
    for my $site (sort keys %{$call_sites{$id}}) {
        print "  $site\n";
        last if ++$shown >= 20;
    }
    print "  ... (+", $count - 20, " more)\n" if $count > 20;
