#!/usr/bin/perl
use strict;
use warnings;

my $ROOT='/bench/repo'; my $MOD='github.com/usememos/memos';
my (%sym,%dir2ip,%calls,%meth_by_name);

# method names too common to attribute via .Name( alone
my %collision = map{$_=>1} qw(
  Len Swap Less Next String Error Validate Kind Format Start Stop Close Read Write Run
  Init Open Flush Seek Sync Done Wait Lock Unlock Serve Handle ServeHTTP RoundTrip
  MarshalJSON UnmarshalJSON Scan Value String Context
);

sub rf{open my $f,'<',$_[0]or return'';local$/;my$c=<$f>;close$f;$c}
sub gofiles{my($b,$t)=@_;open my $f,'-|','find',$b,'-name','*.go'or die$!;my@o;chomp(@o=<$f>);close$f;$t?@o:grep{!/_test\.go$/}@o}
sub ipdir{my$d=shift;return"$MOD/internal"if$d eq"$ROOT/internal";$d=~m{^$ROOT/internal/(.+)$}?"$MOD/internal/$1":undef}
sub pkg{($_[0]=~/^package\s+(\w+)/m)?$1:''}
sub imports{my($c)=@_;my%i;while($c=~/^\s*(\w+)\s+"([^"]+)"/mg){$i{$2}=$1}while($c=~/^\s*"([^"]+)"/mg){my$p=$1;next if$i{$p};($i{$p}=$p)=~s{.*/}{}}%i}
sub recv{my$r=shift;return''unless$r;$r=~s/^\*//;$r=~s/^[\w.]+\.//;$r}
sub decl{my($l,$a,$i)=@_;my$d=$l;my$j=$i;while($d!~/\)\s*(?:\([^)]*\)\s*)?[\w*]+\s*\(/&&$j<@$a-1){$j++;$d.=" ".$a->[$j]}
 return['', $1] if $d=~/^func\s+([A-Za-z_]\w*)\s*\(/;
 return[recv($1),$2] if $d=~/^func\s+\(([^)]*)\)\s+([A-Za-z_]\w*)\s*\(/; undef}

my %builtin=map{$_=>1}qw(if for switch return func make new len cap append delete panic go defer close copy complex real imag);

# collect symbols
for my $p (gofiles("$ROOT/internal",0)){
  my$c=rf($p); my$pk=pkg($c); my$d=$p;$d=~s{/[^/]+$}{}; my$ip=ipdir($d); $dir2ip{$d}=$ip;
  my@L=split/\n/,$c;
  for my$i(0..$#L){next unless$L[$i]=~/^func\s+/; my$r=decl($L[$i],\@L,$i);next unless$r; my($rc,$nm)=@$r;
    my$id=join'|',$ip,$rc,$nm;
    $sym{$id}={ip=>$ip,pkg=>$pk,rc=>$rc,nm=>$nm,file=>$p,line=>$i+1,dir=>$d};
    push@{$meth_by_name{$nm}},$id if$rc ne '';
  }
}

sub is_decl{my($id,$f,$l)=@_;my@a=split/\n/,rf($f);return 0 if$l<1||$l>@a;return$a[$l-1]=~/^\s*func\s+(\([^)]*\)\s+)?\Q$sym{$id}{nm}\E\s*\(/}
sub add{my($id,$f,$l)=@_;return if is_decl($id,$f,$l);$calls{$id}{"$f:$l"}=1}

