  my$fd=$p;$fd=~s{/[^/]+$}{}; my@L=split/\n/,$c;
  for my$i(0..$#L){my$ln=$i+1;my$ln2=$L[$i]; next if$ln2=~/^\s*\/\//;
    while($ln2=~/\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g){my($a,$fn)=($1,$2);my$ip=$al{$a};next unless$ip&&$ip=~m{^$MOD/internal};my$id=join'|',$ip,'',$fn;add($id,$p,$ln)if$sym{$id}}
    if(exists$dir2ip{$fd}){my$ip=$dir2ip{$fd};while($ln2=~/(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g){my$fn=$1;next if$builtin{$fn};my$id=join'|',$ip,'',$fn;add($id,$p,$ln)if$sym{$id}}}
  }
}

# pass B: methods with unique non-collision names
for my $nm (keys%meth_by_name){
  next unless @{$meth_by_name{$nm}}==1;
  next if $collision{$nm};
  my$id=$meth_by_name{$nm}[0];
  for my $p (gofiles($ROOT,1)){
    my@L=split/\n/,rf($p);
    for my$i(0..$#L){next if$L[$i]=~/^\s*\/\//; while($L[$i]=~/\.(\Q$nm\E)\s*\(/g){add($id,$p,$i+1)}}
  }
}

# pass C: known multi-decl but unambiguous service methods (only one in internal with that exact signature package)
my %service_only = map {$_=>1} qw(CompileToStatement ConditionTree ExtractAll ExtractTags ExtractProperties RenderMarkdown RenderHTML GenerateSnippet ValidateContent RenameTag AllowAnonymous ExchangeToken UserInfo Transcribe);
for my $nm (keys %service_only){
  next unless exists $meth_by_name{$nm};
  for my $id (@{$meth_by_name{$nm}}){
    for my $p (gofiles($ROOT,1)){
      my@L=split/\n/,rf($p);
      for my$i(0..$#L){while($L[$i]=~/\.(\Q$nm\E)\s*\(/g){add($id,$p,$i+1)}}
    }
  }
}

my@rank=sort{(scalar(keys%{$calls{$b}//{}})<=>scalar(keys%{$calls{$a}//{}}))||$a cmp$b}keys%sym;
print "FINAL RANKING\n","="x80,"\n";
my$n=0;for my$id(@rank){my$c=scalar keys%{$calls{$id}//{}};next unless$c;last if++$n>25;
 my$s=$sym{$id}; my$sy=$s->{rc}?"($s->{rc}).$s->{nm}":$s->{nm};
 printf"%3d  %s\n     %s:%d\n",$c,$sy,$s->{file},$s->{line}}
print "\nWINNER DETAIL\n";
my$top=$rank[0];for my$id(@rank){if(scalar(keys%{$calls{$id}//{}})){ $top=$id;last}}
my$s=$sym{$top};my$sy=$s->{rc}?"($s->{rc}).$s->{nm}":$s->{nm};
print "$sy => ",scalar(keys%{$calls{$top}})," sites\n";
for my$site(sort keys%{$calls{$top}}){print"  $site\n"}

